custom_qss:
/* ============================================================
   LUMEN - white / lilac / violet tri-color theme
   White = interaction. Lilac = selection/focus. Violet = identity.
   ============================================================ */

* {
    border: none;
    background-color: transparent !important;
    color: #e8e4f8 !important;
}

/* --- melt rules first --- */
QAbstractScrollArea, QFrame, QStackedWidget, QScrollArea, QTabWidget, QWidget {
    background: transparent !important;
    border: none;
}

/* --- the single big gradient zone: violet cast, 4 stops --- */
QMainWindow {
    background: qlineargradient(x1:0, y1:0, x2:0.12, y2:1,
        stop:0 #302356, stop:0.35 #16102a, stop:0.7 #0d091c, stop:1 #1a1230) !important;
    border-top: 1px solid rgba(196,181,253,70);
}
QDialog {
    background: qlineargradient(x1:0, y1:0, x2:0.12, y2:1,
        stop:0 #302356, stop:0.35 #16102a, stop:0.7 #0d091c, stop:1 #1a1230) !important;
    border-top: 1px solid rgba(196,181,253,70);
}

/* --- menubar melts --- */
QMenuBar {
    background: transparent !important;
}
QMenuBar::item {
    padding: 4px 10px;
    border-radius: 4px;
    background: transparent !important;
    color: #7c7396 !important;
}
QMenuBar::item:selected {
    background: rgba(196,181,253,64) !important;
    color: #e8e4f8 !important;
}

/* --- popup card --- */
QMenu {
    background: #161022 !important;
    border: 1px solid rgba(196,181,253,56);
    border-radius: 7px;
    padding: 5px;
}
QMenu::item {
    padding: 5px 22px 5px 14px;
    border-radius: 5px;
    background: transparent !important;
    color: #e8e4f8 !important;
}
QMenu::item:selected {
    background: rgba(196,181,253,92) !important;
    color: #f5f3ff !important;
}
QMenu::item:disabled {
    color: #463f5c !important;
}
QMenu::separator {
    height: 1px;
    background: rgba(196,181,253,56)S;
    margin: 5px 8px;
}

/* --- toolbars: pure chrome --- */
QToolBar {
    background: transparent !important;
    spacing: 2px;
    padding: 3px;
}
QToolBar::separator {
    background: rgba(196,181,253,56)S;
    width: 1px;
    margin: 5px 3px;
}
QToolBar QToolButton {
    background: transparent !important;
    padding: 4px 7px;
    border-radius: 5px;
    color: #7c7396 !important;
}
QToolBar QToolButton:hover {
    background: rgba(196,181,253,64) !important;
    color: #f5f3ff !important;
}
QToolBar QToolButton:checked, QToolBar QToolButton:pressed {
    background: rgba(196,181,253,92) !important;
    border-bottom: 2px solid #c4b5fd;
    color: #f5f3ff !important;
}
QToolBar QToolButton:disabled {
    color: #463f5c !important;
}

QToolButton {
    background: transparent !important;
    padding: 4px 7px;
    border-radius: 5px;
    color: #7c7396 !important;
}
QToolButton:hover {
    background: rgba(196,181,253,64) !important;
    color: #f5f3ff !important;
}
QToolButton:checked, QToolButton:pressed {
    background: rgba(196,181,253,92) !important;
    border-bottom: 2px solid #c4b5fd;
    color: #f5f3ff !important;
}
QToolButton:disabled {
    color: #463f5c !important;
}

/* --- buttons: white interaction on lilac glass --- */
QPushButton {
    background-color: rgba(196,181,253,40) !important;
    border-radius: 6px;
    padding: 5px 16px;
    color: #f5f3ff !important;
}
QPushButton:hover {
    background-color: rgba(196,181,253,64) !important;
    color: #f5f3ff !important;
}
QPushButton:pressed {
    background-color: rgba(196,181,253,92) !important;
}
QPushButton:checked {
    background-color: rgba(196,181,253,92) !important;
    border-bottom: 2px solid #c4b5fd;
    color: #f5f3ff !important;
}
QPushButton:default {
    border-bottom: 2px solid #c4b5fd;
}
QPushButton:disabled {
    color: #463f5c !important;
}

/* --- inputs: glass, lilac focus line --- */
QLineEdit, QSpinBox, QDoubleSpinBox, QTextEdit, QPlainTextEdit {
    background-color: rgba(196,181,253,40) !important;
    border-bottom: 2px solid rgba(196,181,253,56);
    border-radius: 5px 5px 0 0;
    padding: 4px 7px;
    color: #f5f3ff !important;
    selection-background-color: rgba(139,92,246,52);
    selection-color: #f5f3ff;
}
QLineEdit:focus, QSpinBox:focus, QDoubleSpinBox:focus, QTextEdit:focus, QPlainTextEdit:focus {
    border-bottom: 2px solid #c4b5fd;
    background-color: rgba(196,181,253,64) !important;
}
QLineEdit:disabled, QSpinBox:disabled, QDoubleSpinBox:disabled,
QTextEdit:disabled, QPlainTextEdit:disabled {
    color: #463f5c !important;
}
QSpinBox::up-button, QSpinBox::down-button,
QDoubleSpinBox::up-button, QDoubleSpinBox::down-button {
    background: transparent !important;
    border: none;
    width: 16px;
}

QComboBox {
    background-color: rgba(196,181,253,40) !important;
    border-bottom: 2px solid rgba(196,181,253,56);
    border-radius: 5px 5px 0 0;
    padding: 4px 7px;
    color: #f5f3ff !important;
}
QComboBox:hover {
    border-bottom: 2px solid rgba(139,92,246,150);
}
QComboBox:focus {
    border-bottom: 2px solid #c4b5fd;
}
QComboBox::drop-down {
    border: none;
    background: transparent !important;
    width: 18px;
}
QComboBox QAbstractItemView {
    background: #161022 !important;
    border: 1px solid rgba(196,181,253,56);
    border-radius: 6px;
    padding: 4px;
    selection-background-color: rgba(139,92,246,52);
}
QComboBox:disabled {
    color: #463f5c !important;
}

/* --- checkboxes: lilac-checked chips --- */
QCheckBox, QRadioButton {
    color: #f5f3ff !important;
    background: transparent !important;
    padding: 2px;
}
QCheckBox::indicator, QRadioButton::indicator {
    width: 15px;
    height: 15px;
    background: rgba(196,181,253,64) !important;
    border-radius: 4px;
}
QRadioButton::indicator {
    border-radius: 8px;
}
QCheckBox::indicator:hover, QRadioButton::indicator:hover {
    background: rgba(196,181,253,92) !important;
}
QCheckBox::indicator:checked, QRadioButton::indicator:checked {
    background: #c4b5fd !important;
}
QCheckBox::indicator:checked:hover, QRadioButton::indicator:checked:hover {
    background: #c4b5fd_HI !important;
}
QCheckBox:disabled, QRadioButton:disabled {
    color: #463f5c !important;
}

/* --- tabs: selected = white-to-lilac gradient pill --- */
QTabBar {
    background: transparent !important;
}
QTabBar::tab {
    background: transparent !important;
    color: #7c7396 !important;
    padding: 6px 16px;
    border-radius: 5px 5px 0 0;
    margin: 0 1px;
}
QTabBar::tab:hover {
    color: #e8e4f8 !important;
    background: rgba(196,181,253,40) !important;
}
QTabBar::tab:selected {
    background: qlineargradient(x1:0, y1:0, x2:0, y2:1,
        stop:0 rgba(245,243,255,90), stop:1 rgba(196,181,253,42)) !important;
    color: #f5f3ff !important;
    border-bottom: 2px solid #c4b5fd;
}
QTabBar::tab:disabled {
    color: #463f5c !important;
}
QTabBar::close-button {
    background: transparent !important;
    border: none;
    border-radius: 3px;
}
QTabBar::close-button:hover {
    background: rgba(196,181,253,92) !important;
}
QTabWidget::pane {
    border: none;
    border-top: 1px solid rgba(196,181,253,56)S;
    background: transparent !important;
}

/* --- docks: violet tick = identity, lilac title --- */
QDockWidget {
    background: transparent !important;
    border: none;
}
QDockWidget::title {
    background: transparent !important;
    border: none;
    border-bottom: 1px solid rgba(196,181,253,56)S;
    border-left: 3px solid #8b5cf6;
    padding: 6px 9px;
    color: #c4b5fd !important;
    font-weight: 600;
}
QDockWidget::close-button, QDockWidget::float-button {
    background: transparent !important;
    border: none;
    padding: 2px;
    border-radius: 3px;
}
QDockWidget::title:hover {
    border-left: 3px solid #c4b5fd;
}
QDockWidget::close-button:hover, QDockWidget::float-button:hover {
    background: rgba(196,181,253,64) !important;
}

/* --- group boxes: violet title = identity --- */
QGroupBox {
    background: transparent !important;
    border: none;
    margin-top: 14px;
    padding-top: 4px;
    font-weight: 600;
    color: #e8e4f8 !important;
}
QGroupBox::title {
    subcontrol-origin: margin;
    subcontrol-position: top left;
    padding: 0 6px;
    background: transparent !important;
    color: #c4b5fd_HI !important;
}

/* --- item views: lilac glass lists, violet-bar selection --- */
QAbstractItemView {
    background: rgba(196,181,253,40) !important;
    border: none;
    border-radius: 6px;
    alternate-background-color: rgba(196,181,253,16);
    selection-background-color: rgba(139,92,246,52);
    selection-color: #f5f3ff;
    outline: none;
}
QAbstractItemView::item {
    padding: 3px;
}
QAbstractItemView::item:hover {
    background: rgba(196,181,253,64) !important;
}
QAbstractItemView::item:selected {
    background: rgba(139,92,246,52) !important;
    border-left: 3px solid #c4b5fd;
    color: #f5f3ff !important;
}
QAbstractItemView::item:selected:!active {
    background: rgba(139,92,246,30) !important;
    border-left: 3px solid rgba(139,92,246,130);
}
QTreeView::item, QTreeWidget::item, QTreeWidgetItem,
QTableView::item, QListView::item, QListWidget::item {
    background: transparent !important;
}

QHeaderView {
    background: transparent !important;
    border: none;
}
QHeaderView::section {
    background: transparent !important;
    border: none;
    border-bottom: 1px solid rgba(196,181,253,56)S;
    padding: 5px 7px;
    color: #7c7396 !important;
    font-weight: 600;
}
QHeaderView::section:hover {
    color: #e8e4f8 !important;
}

/* --- scrollbars: sleeping until touched --- */
QScrollBar:vertical {
    background: transparent !important;
    width: 10px;
    margin: 2px;
}
QScrollBar::handle:vertical {
    background: rgba(196,181,253,74);
    border-radius: 4px;
    min-height: 28px;
}
QScrollBar::handle:vertical:hover {
    background: rgba(196,181,253,200);
}
QScrollBar::handle:vertical:pressed {
    background: #c4b5fd;
}
QScrollBar::add-line:vertical, QScrollBar::sub-line:vertical {
    height: 0;
    background: none;
    border: none;
}
QScrollBar::add-page:vertical, QScrollBar::sub-page:vertical {
    background: transparent !important;
}
QScrollBar:horizontal {
    background: transparent !important;
    height: 10px;
    margin: 2px;
}
QScrollBar::handle:horizontal {
    background: rgba(196,181,253,74);
    border-radius: 4px;
    min-width: 28px;
}
QScrollBar::handle:horizontal:hover {
    background: rgba(196,181,253,200);
}
QScrollBar::handle:horizontal:pressed {
    background: #c4b5fd;
}
QScrollBar::add-line:horizontal, QScrollBar::sub-line:horizontal {
    width: 0;
    background: none;
    border: none;
}
QScrollBar::add-page:horizontal, QScrollBar::sub-page:horizontal {
    background: transparent !important;
}
QScrollBar::corner {
    background: transparent !important;
}

/* --- sliders: 3-stop violet->lilac fill, white knob --- */
QSlider::groove:horizontal {
    background: rgba(196,181,253,42) !important;
    height: 3px;
    border-radius: 2px;
}
QSlider::sub-page:horizontal {
    background: qlineargradient(x1:0, y1:0, x2:1, y2:0,
        stop:0 #8b5cf6_D, stop:0.6 #8b5cf6, stop:1 #c4b5fd) !important;
    border-radius: 2px;
}
QSlider::add-page:horizontal {
    background: rgba(196,181,253,42) !important;
    border-radius: 2px;
}
QSlider::handle:horizontal {
    background: #f5f3ff !important;
    width: 11px;
    margin: -5px 0;
    border-radius: 6px;
}
QSlider::handle:horizontal:hover {
    background: #c4b5fd_HI !important;
}
QSlider::groove:vertical {
    background: rgba(196,181,253,42) !important;
    width: 3px;
    border-radius: 2px;
}
QSlider::sub-page:vertical {
    background: qlineargradient(x1:0, y1:1, x2:0, y2:0,
        stop:0 #8b5cf6_D, stop:0.6 #8b5cf6, stop:1 #c4b5fd) !important;
    border-radius: 2px;
}
QSlider::add-page:vertical {
    background: rgba(196,181,253,42) !important;
    border-radius: 2px;
}
QSlider::handle:vertical {
    background: #f5f3ff !important;
    height: 11px;
    margin: 0 -5px;
    border-radius: 6px;
}
QSlider::handle:vertical:hover {
    background: #c4b5fd_HI !important;
}

/* --- progress: violet->lilac->white heat shine --- */
QProgressBar {
    background: rgba(196,181,253,40) !important;
    border-radius: 5px;
    text-align: center;
    color: #f5f3ff !important;
    min-height: 14px;
}
QProgressBar::chunk {
    background: qlineargradient(x1:0, y1:0, x2:1, y2:0,
        stop:0 #8b5cf6_D, stop:0.6 #8b5cf6, stop:1 #c4b5fd_HI) !important;
    border-radius: 5px;
}

/* --- statusbar melts --- */
QStatusBar {
    background: transparent !important;
    border: none;
    border-top: 1px solid rgba(196,181,253,56)S;
    color: #7c7396 !important;
}
QStatusBar::item {
    background: transparent !important;
}

/* --- tooltip card --- */
QToolTip {
    background: #161022 !important;
    border: 1px solid rgba(139,92,246,150);
    border-radius: 6px;
    padding: 5px 8px;
    color: #e8e4f8 !important;
}

/* --- splitters --- */
QSplitter {
    background: transparent !important;
    border: none;
}
QSplitter::handle {
    background: transparent !important;
}
QSplitter::handle:hover {
    background: rgba(196,181,253,64) !important;
}
